<script setup lang="ts">import type { SaleReceipt } from '../types'; defineProps<{ receipt: SaleReceipt | null }>(); defineEmits<{ close: [] }>(); function printReceipt(){ window.print() }</script>
<template><div v-if="receipt" class="overlay" role="dialog" aria-modal="true"><article class="receipt"><h2>体育用品门店</h2><p>销售小票</p><dl><dt>单号</dt><dd>{{ receipt.orderNo }}</dd><dt>时间</dt><dd>{{ receipt.occurredAt }}</dd></dl>
  <table><tbody><tr v-for="line in receipt.lines" :key="line.id"><td>{{ line.skuCode }} × {{ line.quantity }}</td><td>¥{{ line.actualAmount.toFixed(2) }}</td></tr></tbody></table>
  <p>优惠：¥{{ receipt.discountAmount.toFixed(2) }}</p><strong>实收：¥{{ receipt.actualAmount.toFixed(2) }}</strong><p>支付：{{ receipt.payments.map(p => p.methodCode).join('、') }}</p>
  <footer><button type="button" @click="printReceipt">打印小票</button><button type="button" @click="$emit('close')">关闭</button></footer></article></div></template>
<style scoped>.overlay{position:fixed;inset:0;background:#0f172a88;display:grid;place-items:center;z-index:30}.receipt{background:white;padding:1.5rem;width:min(25rem,90vw)}dl{display:grid;grid-template-columns:auto 1fr;gap:.4rem}dd{margin:0;text-align:right}table{width:100%}td:last-child{text-align:right}footer{display:flex;gap:.5rem;justify-content:flex-end}@media print{.overlay{position:static;background:none}.receipt{width:80mm}footer{display:none}}</style>
